// Exemplo de dados e colunas
const data = [
    { name: "João", age: 25, city: "São Paulo" },
    { name: "Maria", age: 30, city: "Rio de Janeiro" },
    { name: "Carlos", age: 22, city: "Belo Horizonte" },
    { name: "Ana", age: 28, city: "Curitiba" },
    // Mais dados...
  ];
  
  const columns = [
    {
      Header: "Nome",
      accessor: "name", // corresponde à chave de "name" em cada item de data
    },
    {
      Header: "Idade",
      accessor: "age", // corresponde à chave de "age" em cada item de data
    },
    {
      Header: "Cidade",
      accessor: "city", // corresponde à chave de "city" em cada item de data
    },
  ];
  
  const App = () => {
    console.log("Dados passados para a tabela:", data);
    console.log("Colunas passadas para a tabela:", columns);
  
    return (
      <div>
        <h1>Minha Tabela com Exportação</h1>
        <TableWithExport data={data} columns={columns} />
      </div>
    );
  };
  
  export default App;
